            return True, None
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except UnicodeDecodeError:
            self._error(400, "key must be valid UTF-8")
            return True, None
        if not key or "/" in key:
            self._error(400, "key must be non-empty and must not contain '/'")
            return True, None
        return True, key

