                self._json(200, {"status": "ok"})
                return
            if path == "/v1/keys":
                self._json(200, {"keys": self.server.store.keys()})
                return
            matched, key = self._route_key()
            if matched:
                if key is None:
                    return
                found, value = self.server.store.get(key)
                if found:
